import itertools

def get_reachable(initial_tuples, target_set, max_iter=100):
    reachable = set(initial_tuples)
    for _ in range(max_iter):
        new_tuples = set()
        for v in reachable:
            for w in reachable:
                res = tuple(v[i] + w[i] for i in range(len(v)))
                if all(-2 <= x <= 2 for x in res):
                    if res not in reachable:
                        new_tuples.add(res)
        for v in reachable:
            for w in reachable:
                res = tuple(max(v[i], w[i]) for i in range(len(v)))
                if all(-2 <= x <= 2 for x in res):
                    if res not in reachable:
                        new_tuples.add(res)
        if not new_tuples:
            break
        reachable.update(new_tuples)
        if all(t in reachable for t in target_set):
            return True
    return False

def test_s2_n2():
    target = list(itertools.product([-1, 0, 1], repeat=2))
    possible_v = list(itertools.product([-1, 0, 1], repeat=2))
    for v1, v2 in itertools.combinations_with_replacement(possible_v, 2):
        if get_reachable([v1, v2], target, 50):
            return v1, v2
    return None

print(test_s2_n2())
